FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 081: how far a slanted sheet metal bend's far end tilts. Generated by tools/fixtures/gen-batch-081.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

function knotsProbe(knots) returns array
{
    var out = [];
    for (var i = 0; i < size(knots); i += 1)
        out = append(out, roundToPrecision(knots[i], 9));
    return out;
}

// A part's B-spline faces: their surfaces (degrees, knots, poles) and their vertices.
function splineFaces(context is Context, part is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qGeometry(qOwnedByBody(part, EntityType.FACE), GeometryType.OTHER_SURFACE)))
    {
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6) };
        try
        {
            const s = evSurfaceDefinition(context, { "face" : face });
            if (s is BSplineSurface)
            {
                var rows = [];
                for (var i = 0; i < size(s.controlPoints); i += 1)
                {
                    var points = [];
                    for (var j = 0; j < size(s.controlPoints[i]); j += 1)
                        points = append(points, round6(s.controlPoints[i][j]));
                    rows = append(rows, points);
                }
                entry.bspline = { "uDegree" : s.uDegree, "vDegree" : s.vDegree, "rational" : s.isRational,
                                  "uKnots" : knotsProbe(s.uKnots), "vKnots" : knotsProbe(s.vKnots), "poles" : rows };
            }
        }
        catch (error)
        {
            entry.bspline = "failed";
        }
        var vertices = [];
        for (var v in evaluateQuery(context, qAdjacent(face, AdjacencyType.VERTEX, EntityType.VERTEX)))
            vertices = append(vertices, round6(evVertexPoint(context, { "vertex" : v })));
        entry.vertices = vertices;
        out = append(out, entry);
    }
    return out;
}

// Each face of a body: its area and its surface's type.
function faceProbe(context is Context, body is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(body, EntityType.FACE)))
    {
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6) };
        try
        {
            entry["type"] = evSurfaceDefinition(context, { "face" : face, "returnBSplinesAsOther" : true }).surfaceType;
        }
        catch (error)
        {
            entry["type"] = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// sheet-metal-loft: batch 044 c001's L to an L (shifted 10 mm along y, 20 mm up), the bend radius 2
export function c001(context is Context, id is Id)
{
    const p1 = newSketchOnPlane(context, id + "p1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(p1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 0) * millimeter });
    skLineSegment(p1, "l2", { "start" : vector(30, 0) * millimeter, "end" : vector(30, 20) * millimeter });
    skSolve(p1);
    const p2 = newSketchOnPlane(context, id + "p2", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(p2, "l1", { "start" : vector(0, 10) * millimeter, "end" : vector(30, 10) * millimeter });
    skLineSegment(p2, "l2", { "start" : vector(30, 10) * millimeter, "end" : vector(30, 30) * millimeter });
    skSolve(p2);
    sheetMetalLoft(context, id + "sm1", { "surfaceOperationType" : NewSurfaceOperationType.NEW, "profile1" : qOwnedByBody(qBodyType(qCreatedBy(id + "p1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "profile2" : qOwnedByBody(qBodyType(qCreatedBy(id + "p2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "matchConnections" : false, "chordalTolerance" : 0.1 * millimeter, "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 2 * millimeter, "flipDirectionUp" : false });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID)), "ends" : splineFaces(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID)) };
}

